from .domain import validate_rubric


def official_rubric():
    def row(cid, name, section, kind, weight, instruction, na_rule="", levels=None, roles=None):
        result = {"id": cid, "name": name, "section": section, "kind": kind, "weight": weight,
                  "instruction": instruction, "na_allowed": bool(na_rule), "na_rule": na_rule,
                  "positive_evidence_roles": roles or ["operator"]}
        if levels:
            result["levels"] = [{"score": score, "description": desc} for score, desc in levels]
        return result
    return validate_rubric({"name": "Freedom Broker · официальный чек-лист чатов", "criteria": [
        row("contact", "Установление контакта", "Начало и понимание запроса", "binary", 10,
            "Да — оператор поздоровался на языке клиента и представился в первом ответе. Проверь именно первую реплику operator: оба условия обязательны. Если в ней нет приветствия ИЛИ представления, ответ Нет, даже если далее дан полезный ответ. Приветствие и имя бота не засчитываются оператору."),
        row("discovery", "Выявление потребности", "Начало и понимание запроса", "binary", 15,
            "Сначала определи, были ли в исходном запросе действительно недостающие существенные детали. Если данных хватало с самого начала, обязательно N/A, даже если оператор учёл детали и успешно ответил. Да — недостающие данные были нужны, оператор учёл уже известное и задал нужное уточнение до ответа. Нет — нужное уточнение пропущено или заменено неуместным вопросом. Один лишь учёт известных деталей без нужного уточнения не означает Да. Не поощряйте лишние вопросы.",
            "Данных для ответа хватало с самого начала."),
        row("identification", "Идентификация", "Безопасность и решение", "binary", 20,
            "Да — проверка личности подтверждена до раскрытия данных или защищённого действия. Если проверка требовалась, но не подтверждена в чате, Нет. Нельзя считать отсутствие свидетельств проверкой. Системное сообщение может подтверждать идентификацию, но только до защищённого действия.",
            "Запрос не требовал идентификации, например общий вопрос о тарифах.", roles=["operator", "system"]),
        row("consultation", "Корректная и полная консультация", "Безопасность и решение", "numeric", 20,
            "Оцените ответ или следующий шаг по ступеням. Не путайте полноту решения и ясность речи. Не выдумывайте тарифы или внутренние регламенты. Если без базы знаний нельзя проверить фактическую корректность, укажите ограничение и неоднозначность; это само по себе не разрешает N/A.",
            "Чат закончился до того, как клиент сформулировал запрос.",
            [(0, "Ответа по существу нет или ключевая рекомендация ошибочна."), (5, "Есть общая подсказка, но клиенту всё ещё непонятно, как действовать."),
             (10, "Часть запроса закрыта, существенный вопрос остался открытым."), (15, "Основной вопрос решён, пропущена второстепенная деталь."),
             (20, "Все существенные вопросы закрыты или дан корректный следующий шаг.")]),
        row("empathy", "Эмпатия и клиентоориентированность", "Ведение и завершение диалога", "binary", 15,
            "Да — оператор вежлив и, если клиент выразил недовольство или описал неудобство, отреагировал на конкретную проблему. При отсутствии недовольства достаточно вежливого общения, извинение не обязательно. Отсутствие приветствия само по себе не доказывает невежливость или отсутствие эмпатии. Шаблонная вежливость не заменяет реакцию на конкретное неудобство."),
        row("dialogue", "Управление диалогом, скорость и грамотность", "Ведение и завершение диалога", "numeric", 15,
            "Оцените ясность, порядок ответов и предупреждение об ожидании по ступеням. Порог первой реакции в 3 минуты, теги и вложения в оценку НЕ входят. Не вводите произвольный порог ожидания.",
            levels=[(0, "Из-за бессвязных или противоречивых реплик ход диалога непонятен."), (4, "Клиенту приходится переспрашивать из-за формулировок или порядка ответов."),
                    (7, "Один заметный сбой, но клиент может понять ответ и продолжить."), (10, "Ответы ясные и связные. Если было явное ожидание, оператор предупредил.")]),
        row("closure", "Завершение", "Ведение и завершение диалога", "binary", 5,
            "Да — оператор подвёл итог ИЛИ предложил дальнейшую помощь, И попрощался. Одного прощания без итога или предложения помощи недостаточно. Если оператор закрыл чат без прощания при возможности завершить, Нет.",
            "Чат оборвался до возможности его завершить."),
        row("critical", "Грубые ошибки", "Грубые нарушения", "flag", 0,
            "Да — выявлено оскорбление клиента, предложение платной услуги в обход компании или раскрытие конфиденциальной информации. Нет — ни одно из трёх не выявлено. Самого предложения перевести деньги лично оператору для инвестирования или дать личный номер для частной платной консультации достаточно, согласие и перевод не нужны. Флаг отмечается отдельно и НЕ обнуляет общий балл.")
    ]})
